package com.marketplace;
import java.util.*;import java.math.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api") public class Catalog {
 final Db d;final Access a;Catalog(Db d,Access a){this.d=d;this.a=a;}
 static final String SELECT="select p.*,c.name category,s.name seller,v.id variant_id,v.price,v.original_price,v.stock-v.reserved available,coalesce((select round(avg(rating),1) from reviews r where r.product_id=p.id and visible),0) rating,(select count(*) from reviews r where r.product_id=p.id and visible) review_count from products p join categories c on c.id=p.category_id join stores s on s.id=p.seller_id join lateral(select * from variants where product_id=p.id order by id limit 1)v on true ";
 @GetMapping("/categories") Object categories(){return d.all("select * from categories order by id");}
 @GetMapping("/products") Object list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")long category,@RequestParam(defaultValue="0")BigDecimal min,@RequestParam(defaultValue="100000")BigDecimal max,@RequestParam(defaultValue="0")int rating,@RequestParam(defaultValue="false")boolean stock,@RequestParam(defaultValue="0")long seller,@RequestParam(defaultValue="newest")String sort,@RequestParam(defaultValue="1")int page){
 if(q.length()>100||page<1||page>10000||min.signum()<0||max.compareTo(min)<0||rating<0||rating>5)throw new IllegalArgumentException();
 String filter=" where p.active and s.active and (?='' or to_tsvector('english',p.title || ' ' || p.brand || ' ' || p.description) @@ plainto_tsquery('english',?)) and (?=0 or category_id=?) and v.price between ? and ? and (not ? or v.stock-v.reserved>0) and (?=0 or p.seller_id=?) and coalesce((select avg(rating) from reviews where product_id=p.id and visible),0)>=?";
 Object[] params={q,q,category,category,min,max,stock,seller,seller,rating};String order=switch(sort){case "price"->"v.price asc";case "price_desc"->"v.price desc";case "rating"->"rating desc";case "relevance"->"ts_rank(to_tsvector('english',p.title || ' ' || p.brand || ' ' || p.description),plainto_tsquery('english',?)) desc";default->"p.id desc";};
 List<Object> args=new ArrayList<>(Arrays.asList(params));if(sort.equals("relevance"))args.add(q);args.add((page-1)*12);
 long total=d.id("select count(*) from ("+SELECT+filter+") x",params);
 return Map.of("items",d.all(SELECT+filter+" order by "+order+",p.id limit 12 offset ?",args.toArray()),"page",page,"total",total,"pages",Math.max(1,(total+11)/12));}
 @GetMapping("/suggestions") Object suggest(@RequestParam String q){if(q.length()>100)throw new IllegalArgumentException();return d.all("select id,title from products where active and title ilike ? order by id limit 6","%"+q+"%");}
 @GetMapping("/products/{id}") Object detail(@PathVariable long id){var p=d.one(SELECT+" where p.id=? and p.active and s.active",id);p.put("variants",d.all("select *,stock-reserved available from variants where product_id=? order by id",id));p.put("reviews",d.all("select r.id,r.rating,r.title,r.body,r.created_at,u.name,true verified from reviews r join users u on u.id=r.user_id where product_id=? and visible order by r.id desc",id));return p;}
 @GetMapping("/stores") Object stores(){return d.all("select id,name from stores where active order by id");}
 @GetMapping("/addresses") Object addresses(HttpSession s){return d.all("select * from addresses where user_id=? order by id",a.uid(s));}
 @PostMapping("/addresses") Object address(HttpSession s,@RequestBody Map<String,String>b){for(String k:List.of("name","line1","city","state","zip"))check(b.get(k),1,150);return Map.of("id",d.id("insert into addresses(user_id,name,line1,city,state,zip) values(?,?,?,?,?,?) returning id",a.uid(s),b.get("name"),b.get("line1"),b.get("city"),b.get("state"),b.get("zip")));}
 @GetMapping("/cart") Object cart(HttpSession s){return cartFor(a.uid(s));}
 List<Map<String,Object>> cartFor(long uid){return d.all("select ci.variant_id,ci.quantity,v.color,v.price,v.stock-v.reserved available,p.id product_id,p.title,p.image,s.name seller from cart_items ci join variants v on v.id=ci.variant_id join products p on p.id=v.product_id join stores s on s.id=p.seller_id where ci.user_id=? order by ci.variant_id",uid);}
 record CartInput(long variantId,int quantity){}
 @PostMapping("/cart") Object add(HttpSession s,@RequestBody CartInput b){long uid=a.role(s,"CUSTOMER");if(b.quantity()<1||b.quantity()>20)throw new IllegalArgumentException();d.one("select v.id from variants v join products p on p.id=v.product_id join stores st on st.id=p.seller_id where v.id=? and p.active and st.active",b.variantId());d.exec("insert into cart_items values(?,?,?) on conflict(user_id,variant_id) do update set quantity=least(20,cart_items.quantity+excluded.quantity)",uid,b.variantId(),b.quantity());return cartFor(uid);}
 @PutMapping("/cart/{id}") Object quantity(HttpSession s,@PathVariable long id,@RequestBody CartInput b){if(b.quantity()<1||b.quantity()>20)throw new IllegalArgumentException();d.exec("update cart_items set quantity=? where user_id=? and variant_id=?",b.quantity(),a.uid(s),id);return cartFor(a.uid(s));}
 @DeleteMapping("/cart/{id}") Object remove(HttpSession s,@PathVariable long id){d.exec("delete from cart_items where user_id=? and variant_id=?",a.uid(s),id);return Map.of("ok",true);}
 @GetMapping("/wishlist") Object wishlist(HttpSession s){return d.all(SELECT+" join wishlists w on w.product_id=p.id where w.user_id=?",a.uid(s));}
 @PostMapping("/wishlist/{id}") Object wish(HttpSession s,@PathVariable long id){d.exec("insert into wishlists values(?,?) on conflict do nothing",a.uid(s),id);return Map.of("ok",true);}
 @DeleteMapping("/wishlist/{id}") Object unwish(HttpSession s,@PathVariable long id){d.exec("delete from wishlists where user_id=? and product_id=?",a.uid(s),id);return Map.of("ok",true);}
 record Review(int rating,String title,String body){}
 @PostMapping("/products/{id}/reviews") @Transactional Object review(HttpSession s,@PathVariable long id,@RequestBody Review b){long uid=a.role(s,"CUSTOMER");check(b.title(),1,100);check(b.body(),1,2000);if(b.rating()<1||b.rating()>5)throw new IllegalArgumentException();if(d.id("select count(*) from order_items i join orders o on o.id=i.order_id where o.user_id=? and o.payment_state='PAID' and i.product_id=?",uid,id)==0)throw new Failure(403,"PURCHASE_REQUIRED","A paid purchase is required to review this product");d.exec("insert into reviews(user_id,product_id,rating,title,body) values(?,?,?,?,?) on conflict(user_id,product_id) do update set rating=excluded.rating,title=excluded.title,body=excluded.body,visible=true",uid,id,b.rating(),b.title(),b.body());return Map.of("ok",true);}
 @DeleteMapping("/reviews/{id}") Object deleteReview(HttpSession s,@PathVariable long id){d.exec("delete from reviews where id=? and user_id=?",id,a.uid(s));return Map.of("ok",true);}
 @GetMapping("/notifications") Object notifications(HttpSession s){return d.all("select * from notifications where user_id=? order by id desc limit 50",a.uid(s));}
 @PostMapping("/notifications/read") Object read(HttpSession s){d.exec("update notifications set seen=true where user_id=?",a.uid(s));return Map.of("ok",true);}
 static void check(String s,int min,int max){if(s==null||s.trim().length()<min||s.length()>max)throw new IllegalArgumentException();}
}
